window.REPORT_PRELOAD_CACHE["NFLX.html"] = {"version":"da8983063cae0f7a3261edd694e7cecd09cde5884eb3d0d49997d3c7d0b6c908","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Netflix (NASDAQ: NFLX) 深度研究报告：从全球流媒体霸主到“订阅+广告+体育直播”双引擎现金流机器</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter & Noto Sans SC -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            netflix: {\n              500: '#E50914',\n              600: '#B81D24',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(229, 9, 20, 0.22) 0%, rgba(59, 130, 246, 0.06) 100%);\n      border-left: 3px solid #E50914;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-slate-800 dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-netflix-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/60 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-netflix-500 via-rose-500 to-accent-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-netflix-500 to-rose-700 flex items-center justify-center font-extrabold text-white shadow\">\n        N\n      </div>\n      <div>\n        <div class=\"text-[11px] text-rose-400 font-semibold tracking-wider uppercase\">NASDAQ: NFLX · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">Netflix 深度投资研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">NFLX 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康度与估值重置</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球互联网与数字娱乐研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY25 / 26E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-72 bg-navy-900 text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-6 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-netflix-500 to-rose-700 flex items-center justify-center text-white font-extrabold text-xl shadow-lg shadow-netflix-500/25\">\n            N\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-rose-400 bg-rose-500/15 px-2 py-0.5 rounded\">NASDAQ: NFLX</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Netflix 深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-3 leading-relaxed\">\n          全球流媒体霸主 · 订阅提价 + 广告变现 + 体育直播双引擎现金流机器\n        </p>\n      </div>\n\n      <!-- 实时行情快照栏 -->\n      <div class=\"px-5 py-3 bg-navy-950/60 border-b border-slate-800/80 grid grid-cols-2 gap-2 text-xs\">\n        <div>\n          <span class=\"text-slate-500 block\">参考股价 (2026.11)</span>\n          <span class=\"font-mono font-bold text-white\">$62.95</span>\n          <span class=\"text-emerald-400 text-[11px] ml-1\">市值 ~$260B</span>\n        </div>\n        <div>\n          <span class=\"text-slate-500 block\">远期估值锚</span>\n          <span class=\"font-mono font-bold text-teal-400\">~18.0x P/E</span>\n          <span class=\"text-slate-400 text-[11px] ml-1\">PEG 0.39</span>\n        </div>\n      </div>\n\n      <!-- 目录导航 -->\n      <div class=\"px-3 py-4\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">报告章节目录</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-sm\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-rose-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值重置</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2.5 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-5 border-t border-slate-800/80 bg-navy-950/40 space-y-3\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-3 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-teal-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色研报模式</span>\n          <span class=\"hidden dark:inline\">亮色机构模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-netflix-500 hover:bg-netflix-600 text-white text-xs font-semibold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-72 min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. 执行摘要与核心指标 (Executive Summary)\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元信息条 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex items-center space-x-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-netflix-500/10 text-netflix-600 dark:text-rose-400 font-semibold border border-netflix-500/20\">深度覆盖报告 · 全球流媒体与数字娱乐</span>\n            <span>标的：Netflix, Inc. (NASDAQ: NFLX)</span>\n          </div>\n          <div class=\"flex items-center space-x-4 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>股价：~$62.95 | 市值：~$260B</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/60\">\n          <!-- 背景点阵纹理 -->\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#E50914 1px, transparent 1px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-netflix-500/20 border border-netflix-500/40 text-rose-300 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-netflix-500 animate-pulse\"></span>\n              <span>CORE THESIS · 现金流壁垒持续拓宽 × 2026 估值深度重置下的黄金赔率</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              Netflix (NASDAQ: NFLX) 深度研究报告：从全球流媒体霸主到“订阅+广告+体育直播”双引擎现金流机器\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              历经“流媒体战争”残酷洗牌，Netflix 已确立行业唯一的规模化盈利霸主地位。2025 全年公司实现营收 <strong class=\"text-white\">$45.18B (+15.85%)</strong> 与自由现金流 <strong class=\"text-teal-400\">$9.46B</strong>，ROIC 攀升至 <strong class=\"text-white\">30.1%</strong>。\n              随着 2026 年广告业务向 <strong class=\"text-rose-400\">$30 亿大关</strong>冲刺、WWE Raw 与 NFL 体育直播引爆用户时长，叠加远期 P/E 从 40x 峰值深度压缩至 <strong class=\"text-emerald-400\">~18x (PEG 0.39)</strong>，基本面与估值的显著背离正创造罕见的机构配置窗口。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">商业模式进化</div>\n                <div class=\"text-white font-semibold\">由“纯付费订阅平台”升级为“高ARPU提价 + $3B广告 + 体育直播”双引擎机器</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">资本效率拐点</div>\n                <div class=\"text-teal-400 font-semibold\">自由现金流跃升至 $9.46B，ROIC 高达 30.1%，碾压传统好莱坞竞争对手</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">2026 估值重置机遇</div>\n                <div class=\"text-emerald-400 font-semibold\">远期 P/E 回调至 ~18x（较峰值腰斩超 50%），PEG 仅 0.39，具备极高安全边际</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心指标 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>2026E 预测全年营收</span>\n              <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white\">~$51.2B</span>\n              <span class=\"text-xs font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">TTM $49.74B</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              继 2025 全年实现 $45.18B (+15.85%) 后，提价红利与广告放量驱动双位数稳健扩张。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>2025 全年自由现金流 (FCF)</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white\">$9.46B</span>\n              <span class=\"text-xs font-semibold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">ROIC 30.1%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              净利润达 $10.9B（净利率 24.3%），内容投入进入高效产出期，现金流转化率行业断层领先。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>全球付费用户基数</span>\n              <span class=\"p-1.5 rounded-lg bg-netflix-500/10 text-netflix-600 dark:text-rose-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white\">3.25亿+</span>\n              <span class=\"text-xs font-semibold text-rose-600 dark:text-rose-400 bg-rose-500/10 px-2 py-0.5 rounded\">覆盖超7亿观众</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              付费共享打击成功转化为长期留存，广告版套餐在开通市场贡献超 50% 新增注册。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>当前远期 P/E 估值</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white\">~18.0x</span>\n              <span class=\"text-xs font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">较峰值压缩 &gt;50%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              较 2025 年中 40x 估值高点深度消化，当前 PEG 仅 0.39，兼具成长性与价值安全边际。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-netflix-600 dark:text-rose-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：区域基本盘与广告/直播双引擎</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">收入结构升级：单轨订阅 → 区域量价齐升 + $3B 广告 + 体育直播</span>\n        </div>\n\n        <!-- 交互式可视化面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：交互式 Chart.js 图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">全球四大区域营收结构与月均 ARPU 对比</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">UCAN 贡献核心现金流，EMEA 与 APAC 驱动全球渗透率扩张</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('region')\" id=\"btn-chart-region\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-netflix-600 dark:text-white shadow-sm transition\">区域营收与 ARPU</button>\n                <button onclick=\"switchBizChart('growth')\" id=\"btn-chart-growth\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">2021-2026E 营收与 FCF</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解要点 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业变现模型核心拆解</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-netflix-500/15 text-netflix-600 dark:text-rose-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">欧美提价兑现 + 亚太拉美放量</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      UCAN（北美，占营收 44.2%）与 EMEA（欧洲中东非洲，32.1%）依托强定价权持续提升 ARPU；LATAM（11.9%）与 APAC（11.8%）则以低价广告套餐快速收割增量家庭。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">自研广告技术栈驱动 $30 亿新引擎</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      全面切换至自研第一方广告平台（Netflix Ads Suite），结合程序化购买与精准受众标签，广告层级综合变现效率正追平甚至反超标准无广告套餐。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">大事件直播与互动生态锁定黄金时段</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      《WWE Raw》每周常态化直播、NFL 圣诞大战以及重磅拳击/综合格斗赛事，精准补齐传统点播在“实时并发与品牌广告主高溢价”上的最后一块拼图。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">2026E 广告业务目标</span>\n              <span class=\"font-bold text-netflix-600 dark:text-rose-400\">冲刺 ~$3.0B (成为核心第二增长曲线)</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 三大核心业务引擎卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 引擎 1：区域订阅基本盘 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-netflix-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"px-2.5 py-1 rounded-md bg-netflix-500/10 text-netflix-600 dark:text-rose-400 text-xs font-bold\">核心现金流基石</span>\n              <span class=\"text-xs font-mono text-slate-400\">01 / GLOBAL SUBSCRIPTIONS</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">全球区域订阅基本盘</h3>\n            <div class=\"mt-3 space-y-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <p><strong class=\"text-slate-900 dark:text-white\">区域收入分布：</strong>北美 UCAN 占比 <strong>44.2%</strong>（月均 ARPU 领跑全球）、EMEA 占比 <strong>32.1%</strong>、拉美 LATAM 占比 <strong>11.9%</strong>、亚太 APAC 占比 <strong>11.8%</strong>。</p>\n              <p><strong class=\"text-slate-900 dark:text-white\">增长驱动力：</strong>付费密码共享整治实现用户基数跃升至 3.25 亿+，阶梯式提价策略直接转化为高确定性经常性收入（ARR）。</p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex flex-wrap gap-1.5\">\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">UCAN 44.2%</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">EMEA 32.1%</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">APAC 渗透率高增</span>\n            </div>\n          </div>\n\n          <!-- 引擎 2：广告支持层级 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">高速扩张第二曲线</span>\n              <span class=\"text-xs font-mono text-slate-400\">02 / AD-SUPPORTED TIER</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">广告支持层级（Ad-Tier）</h3>\n            <div class=\"mt-3 space-y-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <p><strong class=\"text-slate-900 dark:text-white\">变现里程碑：</strong>2025 年广告收入实现翻倍以上增长，2026 年正全力冲刺 <strong>$30 亿（$3B）</strong>收入体量，成为拉动整体增速的核心引擎。</p>\n              <p><strong class=\"text-slate-900 dark:text-white\">商业飞轮：</strong>较低入场月费有效降低价格敏感型用户门槛，同时通过全球自研广告技术栈提升 CPM 单价与填充率，实现“低月费+高广告分成”双收。</p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex flex-wrap gap-1.5\">\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">2026E 冲刺 $3B</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">自研广告技术栈</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">低流失率漏斗</span>\n            </div>\n          </div>\n\n          <!-- 引擎 3：体育直播与互动娱乐 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">高溢价生态增量</span>\n              <span class=\"text-xs font-mono text-slate-400\">03 / LIVE SPORTS & GAMING</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">体育直播与互动娱乐</h3>\n            <div class=\"mt-3 space-y-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <p><strong class=\"text-slate-900 dark:text-white\">事件型直播策略：</strong>聚焦《WWE Raw》全年周播权、NFL 圣诞大战等现象级体育与文娱直播，避开天价传统联赛版权通胀，同时最大化广告库存价值。</p>\n              <p><strong class=\"text-slate-900 dark:text-white\">泛娱乐矩阵：</strong>拓展基于热门剧集 IP 的移动与云端游戏、视频播客及线下体验馆，延长用户生命周期价值（LTV）。</p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex flex-wrap gap-1.5\">\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">WWE Raw 周播</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">NFL 圣诞大战</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-medium\">IP 互动游戏/播客</span>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与护城河：内容飞轮与 30.1% ROIC 统治力</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球唯一规模化盈利流媒体)</span>\n        </div>\n\n        <!-- 四重核心护城河网格 + 雷达图 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 壁垒 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-netflix-500/15 text-netflix-600 dark:text-rose-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球化本地原创内容飞轮</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                超过 <strong>60%</strong> 的原创剧集与电影产自美国以外地区（韩国、西班牙、英国、日本、拉美等）。“本地制作、全球分发”模式使单部非英语爆款（如《鱿鱼游戏》系列）的投入产出比远超好莱坞大片。\n              </p>\n            </div>\n\n            <!-- 壁垒 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">强提价权与行业最低流失率</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                即便美国区标准版月费上调至 <strong>$19.99</strong>，Netflix 仍保持全球流媒体最低的用户月度流失率（Churn Rate &lt; 2%）。高频更新的内容库使其成为家庭娱乐的“水电煤级”刚需配置。\n              </p>\n            </div>\n\n            <!-- 壁垒 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">推荐算法与 3.25 亿数据规模效应</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                基于 3.25 亿+付费家庭的实时完播率、暂停与弃剧行为数据，精准指导新剧立项绿灯（Greenlight）与千人千面封面分发，有效降低单部作品的商业扑街风险。\n              </p>\n            </div>\n\n            <!-- 壁垒 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极致的资本回报率 (ROIC 30.1%)</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                内容摊销与现金支出比趋于稳态，庞大用户分母摊薄单集固定制作成本，推动公司投入资本回报率（ROIC）跃升至 <strong>30.1%</strong>，远超传统传媒集团的个位数回报水平。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：护城河五维雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">流媒体行业护城河多维量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Netflix vs 传统好莱坞流媒体 vs 科技巨头综合平台（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n\n        <!-- 盈利效率横向对比柱状图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">流媒体业务营业利润率（Operating Margin）横向统治力对比</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">Netflix 凭借规模效应实现近 30% 营业利润率，而多数传统传媒流媒体仍处于盈亏平衡线挣扎期</p>\n            </div>\n            <span class=\"text-xs font-semibold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2.5 py-1 rounded\">规模效应带来的盈利断层</span>\n          </div>\n          <div class=\"relative h-56 w-full\">\n            <canvas id=\"marginComparisonChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-netflix-600 dark:text-rose-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：传统传媒收缩，双寡头格局成型</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-netflix-500 text-white shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('hollywood')\" data-filter=\"hollywood\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">传统好莱坞传媒</button>\n            <button onclick=\"filterCompetitors('bigtech')\" data-filter=\"bigtech\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">科技巨头生态</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">竞争阵营与代表平台</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">核心商业模式</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">年内容投入规模</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">流媒体盈利能力</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">美国电视时长占比</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争态势评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：Netflix 行业基准 -->\n                <tr data-category=\"core\" class=\"bg-netflix-500/5 dark:bg-netflix-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-netflix-500 text-white text-[10px] font-bold\">行业基准</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">Netflix (NFLX)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">纯粹专注长视频+直播+广告</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">独立 SVOD + AVOD 双引擎</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-bold text-slate-900 dark:text-white\">~$17B - $18B / 年</td>\n                  <td class=\"py-4 px-4 font-bold text-emerald-600 dark:text-emerald-400\">极强 (营业利润率 ~29%)</td>\n                  <td class=\"py-4 px-4 font-bold text-slate-900 dark:text-white\">~8.0% - 8.5% (付费榜首)</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>全赛道统治者：</strong>无传统有线电视衰退包袱，全球本地化内容工业体系最成熟，甚至反向接收传统好莱坞授权剧集实现双赢。\n                  </td>\n                </tr>\n\n                <!-- 行 2：Disney+ / Hulu / ESPN -->\n                <tr data-category=\"hollywood\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Disney+ / Hulu / ESPN</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">传统好莱坞头部 (DIS)</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">捆绑包 (Bundle) + 体育</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~$23B+ (含体育版权)</td>\n                  <td class=\"py-4 px-4 text-amber-600 dark:text-amber-400 font-semibold\">刚跨过盈亏平衡 (利润率 &lt;8%)</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~4.8% - 5.2% (合并计算)</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>核心挑战：</strong>合家欢 IP 与 ESPN 体育底蕴深厚，但传统有线电视（Linear TV）利润持续萎缩，制约其流媒体激进扩张空间。\n                  </td>\n                </tr>\n\n                <!-- 行 3：Max / Paramount+ / Peacock -->\n                <tr data-category=\"hollywood\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Max / Paramount+ / Peacock</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">二线好莱坞传媒集团 (WBD/PARA)</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-rose-500/10 text-rose-600 dark:text-rose-400\">战略收缩 / 寻找并购整合</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">$8B - $12B (持续削减)</td>\n                  <td class=\"py-4 px-4 text-rose-600 dark:text-rose-400 font-semibold\">微利或持续亏损</td>\n                  <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">各自 1.2% - 1.8%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>结构性劣势：</strong>海外发行网络薄弱、资产负债表承压，已被迫放弃“独立挑战 Netflix”，重新向 Netflix 授权经典片库回血。\n                  </td>\n                </tr>\n\n                <!-- 行 4：YouTube (Alphabet) -->\n                <tr data-category=\"bigtech\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">YouTube / YouTube TV</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Alphabet 旗下视频霸主 (GOOGL)</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-accent-500/15 text-accent-700 dark:text-accent-400\">UGC 免费广告 + 虚拟有线电视</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">创作者分成模式 (轻资产)</td>\n                  <td class=\"py-4 px-4 text-emerald-600 dark:text-emerald-400 font-semibold\">极强 (广告印钞机)</td>\n                  <td class=\"py-4 px-4 font-bold text-accent-600 dark:text-accent-400\">~10.5%+ (电视端总时长第一)</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>最大时空争夺者：</strong>在客厅大屏观看总时长上稳居榜首，与 Netflix 在用户注意力与品牌电视广告预算上形成“双寡头”直接竞争。\n                  </td>\n                </tr>\n\n                <!-- 行 5：Amazon Prime Video & Apple TV+ -->\n                <tr data-category=\"bigtech\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Prime Video / Apple TV+</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">科技万亿巨头附属生态 (AMZN/AAPL)</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-300\">主业生态引流补贴工具</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">$7B - $15B (不计短期 ROI)</td>\n                  <td class=\"py-4 px-4 text-slate-500 dark:text-slate-400 font-medium\">附属业务 (Prime 引入默认广告)</td>\n                  <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">Prime ~3.5% / Apple &lt;1%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>生态打法：</strong>Prime Video 凭借默认开启广告迅速切入广告市场，但内容更新频次与独立用户心智黏性仍显著逊于 Netflix。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值重置 (Financial Health & Valuation Reset)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & 2026 Valuation Reset</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：现金流爆发与估值深度重置</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">核心看点：FCF $9.46B 历史新高 vs 远期 P/E 压缩至 ~18x</span>\n        </div>\n\n        <!-- 1. 财务健康度核心指标看板 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase tracking-wider\">Free Cash Flow Inflection</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">自由现金流历史性跨越</h3>\n            <div class=\"mt-3 text-2xl font-extrabold text-slate-900 dark:text-white font-mono\">-$0.16B → +$9.46B</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              自 2021 年自由现金流微幅为负后，随内容支出增速收敛至 ~$17-18B 稳态区间，2025 全年 FCF 飙升至 <strong>$9.46B</strong>，现金流自我造血与股票回购能力极强。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-wider\">Profitability & Capital Efficiency</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">净利润率与 ROIC 跃升</h3>\n            <div class=\"mt-3 text-2xl font-extrabold text-slate-900 dark:text-white font-mono\">净利率 24.3% · ROIC 30.1%</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              2025 全年净利润高达 <strong>$10.9B</strong>，经营杠杆持续释放。资产负债表高度健康，净杠杆率低，具备充裕的现金储备进行股份注销回购以增厚 EPS。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-netflix-600 dark:text-rose-400 uppercase tracking-wider\">2026 Valuation Reset</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">估值泡沫出清，PEG 仅 0.39</h3>\n            <div class=\"mt-3 text-2xl font-extrabold text-slate-900 dark:text-white font-mono\">40.0x → ~18.0x Fwd P/E</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              截至 2026 年 11 月（股价 ~$62.95，市值 ~$260B），市场对成熟期增速放缓的过度担忧已将远期 P/E 压制至 <strong>~18x</strong>，动态 PEG 低至 <strong>0.39</strong>，显著低于标普500及大型科技股均值。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 估值体系演进三阶段阶梯图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Netflix 估值体系与市场定价逻辑演进阶梯</h3>\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-6\">从早期“烧钱换用户”的 P/S 估值，向“高确定性现金流+广告平台”的 DCF 与 PEG 价值重估过渡</p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n            <!-- 阶段 1 -->\n            <div class=\"p-5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200 dark:border-slate-700 flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"text-xs font-bold text-slate-500 dark:text-slate-400\">STAGE 01 · 2015-2021</span>\n                  <span class=\"px-2 py-0.5 rounded bg-slate-200 dark:bg-navy-700 text-[11px] font-mono font-semibold\">EV/Sub · P/S</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-base\">跑马圈地与净增用户叙事</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  市场仅关注季度净增订阅用户数（Net Adds），容忍巨额负自由现金流与举债拍片，一旦用户增速波动即引发剧烈估值杀跌。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-200 dark:border-slate-700 text-xs font-semibold text-slate-500\">\n                估值特征：高波动、纯用户增长驱动\n              </div>\n            </div>\n\n            <!-- 阶段 2 -->\n            <div class=\"p-5 rounded-xl bg-accent-500/5 dark:bg-accent-500/10 border border-accent-500/30 flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400\">STAGE 02 · 2023-2025</span>\n                  <span class=\"px-2 py-0.5 rounded bg-accent-500/20 text-accent-700 dark:text-accent-300 text-[11px] font-mono font-semibold\">Fwd P/E 35x-40x</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-base\">打击共享与 FCF 爆发溢价期</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  付费共享整治释放一次性用户红利，叠加利润率快速扩张，市场给予其长达两年的业绩上修周期，2025 年中远期 P/E 一度冲高至 40x 峰值。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-accent-500/20 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                估值特征：确定性溢价拉满，估值处于历史高位\n              </div>\n            </div>\n\n            <!-- 阶段 3 -->\n            <div class=\"p-5 rounded-xl bg-gradient-to-br from-netflix-500/10 to-teal-500/10 border border-netflix-500/40 flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"text-xs font-bold text-netflix-600 dark:text-rose-400\">STAGE 03 · 2026 当前重置期</span>\n                  <span class=\"px-2 py-0.5 rounded bg-netflix-500/20 text-netflix-700 dark:text-rose-300 text-[11px] font-mono font-semibold\">~18x P/E · PEG 0.39</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-base\">双引擎现金流复利与估值修复</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  停止披露季度用户数后，市场情绪阶段性降温并完成估值重置。当前 ~18x 远期 P/E 已充分计入温和增速预期，而 $3B 广告与体育直播兑现将驱动戴维斯双击。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-netflix-500/20 text-xs font-semibold text-netflix-600 dark:text-rose-400\">\n                估值锚：DCF 自由现金流折现 + EPS 回购复利\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 估值敏感性与多空分歧对比面板 (Bull Case vs Bear Case) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <!-- Bull Case -->\n          <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"inline-flex items-center space-x-1.5 text-emerald-700 dark:text-emerald-400 font-bold text-base\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                <span>乐观重估视角 (Bull Case · 目标 24x-26x P/E)</span>\n              </span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">戴维斯双击潜力</span>\n            </div>\n            <ul class=\"space-y-2.5 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-emerald-600 font-bold mt-0.5\">✓</span>\n                <span><strong>广告业务超预期放量：</strong>自研广告平台全面铺开后，广告收入在 2026-2027 年连续翻倍，推动整体营收维持 13%-15% 复合增速。</span>\n              </li>\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-emerald-600 font-bold mt-0.5\">✓</span>\n                <span><strong>持续提价与回购增厚 EPS：</strong>每年近百亿美元 FCF 用于高效股票回购，推动 EPS 维持 20%+ 增长，当前 18x P/E 具备 35% 以上估值修复空间。</span>\n              </li>\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-emerald-600 font-bold mt-0.5\">✓</span>\n                <span><strong>传统传媒退潮红利：</strong>二线好莱坞流媒体放弃独立扩张，源源不断向 Netflix 输送低成本高热度片库。</span>\n              </li>\n            </ul>\n          </div>\n\n          <!-- Bear Case -->\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"inline-flex items-center space-x-1.5 text-rose-700 dark:text-rose-400 font-bold text-base\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 17h8m0 0V9m0 8l-8-8-4 4-6-6\"/></svg>\n                <span>谨慎压制视角 (Bear Case · 维持 15x-17x P/E)</span>\n              </span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">成熟期增速换挡</span>\n            </div>\n            <ul class=\"space-y-2.5 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-rose-600 font-bold mt-0.5\">!</span>\n                <span><strong>北美与西欧渗透率见顶：</strong>打击密码共享的一次性红利消退后，成熟市场净增用户趋缓，市场可能将其按“传统成熟电信/传媒股”给予较低倍数。</span>\n              </li>\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-rose-600 font-bold mt-0.5\">!</span>\n                <span><strong>短视频与 YouTube 持续分流注意力：</strong>TikTok 与 YouTube 抢占年轻群体碎片化时间，限制电视大屏总观看时长份额进一步突破 10%。</span>\n              </li>\n              <li class=\"flex items-start space-x-2\">\n                <span class=\"text-rose-600 font-bold mt-0.5\">!</span>\n                <span><strong>体育直播版权通胀隐忧：</strong>若未来被迫卷入高价体育联赛长期版权竞标，可能侵蚀好不容易建立的 30%+ ROIC 资本效率。</span>\n              </li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置分析 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-netflix-600 dark:text-rose-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置分析：背离中的安全边际与风险纪律</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置策略：互联网消费核心底仓 · 逢估值回调分批布局</span>\n        </div>\n\n        <!-- 1. 核心投资逻辑双引擎 -->\n        <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n          <h3 class=\"text-base font-bold text-rose-400 mb-4 flex items-center space-x-2\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            <span>核心投资逻辑（Why Invest in NFLX at ~18x Forward P/E）</span>\n          </h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white text-base mb-1.5\">1. 基本面持续创历史新高与估值深度压缩的罕见背离</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                公司 2025-2026 年营收、营业利润率、ROIC（30.1%）及自由现金流（$9.46B）均处于历史最佳状态，但远期 P/E 却从 40x 回落至 ~18x（PEG 0.39），为中长期机构资金提供了极高的安全边际与赔率优势。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white text-base mb-1.5\">2. 全球娱乐消费最确定的“现金流印钞机”</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                跨越了最烧钱的全球基建期后，Netflix 已进入轻边际成本扩张阶段。提价权、$3B 广告业务与低成本事件型体育直播共同保障了未来三年 15%-20% 的稳健 EPS 复利增长。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构缓释机制</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 风险 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 用户时长竞争风险</span>\n                  <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">北美观看时长见顶与短视频/YouTube 分流</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  成熟市场家庭每日娱乐总时长有限，YouTube、TikTok 及游戏持续争夺年轻用户注意力，若观看时长停滞可能削弱后续提价与广告库存扩张空间。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400\">\n                <strong class=\"text-accent-600 dark:text-accent-400\">缓释机制：</strong>切入 WWE/NFL 等必看直播大事件，并扩展播客与移动游戏，抢占非传统剧集消费场景。\n              </div>\n            </div>\n\n            <!-- 风险 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 成本与版权通胀风险</span>\n                  <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">头部内容制作成本与体育版权通胀</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  顶级主创片酬上涨及现场体育赛事版权竞标溢价，若未能匹配相应的广告或新增订阅变现，可能阶段性压制营业利润率扩张斜率。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400\">\n                <strong class=\"text-accent-600 dark:text-accent-400\">缓释机制：</strong>严格控制年度内容现金支出在 ~$17-18B 纪律红线内，优先采购高性价比非英语本地剧集。\n              </div>\n            </div>\n\n            <!-- 风险 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 汇率与新兴市场 ARPU 瓶颈</span>\n                  <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">强势美元汇兑损益与新兴市场消费力</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  超 55% 营收来自海外市场，美元走强直接影响合并报表美元计价增速；同时亚太与拉美新兴市场人均付费能力显著低于欧美，存在 ARPU 天花板。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400\">\n                <strong class=\"text-accent-600 dark:text-accent-400\">缓释机制：</strong>推行外汇对冲策略，并在新兴市场通过“超低月费+高广告变现”提升单用户综合贡献。\n              </div>\n            </div>\n\n            <!-- 风险 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 宏观消费降级风险</span>\n                  <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：低-中</span>\n                </div>\n                <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球宏观经济放缓引发可选消费削减</h4>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                  若全球通胀黏性或就业放缓导致家庭缩减娱乐预算，部分高价无广告套餐用户可能面临降级或退订压力。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400\">\n                <strong class=\"text-accent-600 dark:text-accent-400\">缓释机制：</strong>兼具“口红效应”（居家替代外出高价消费）与低价广告套餐承接网，流失率大幅低于同类产品。\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 仓位配置建议与季度基本面跟踪 KPI 交互核查清单 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 仓位配置建议 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">机构投资组合仓位配置建议</h3>\n            <div class=\"space-y-4 text-xs sm:text-sm\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/70 border border-slate-200 dark:border-slate-700\">\n                <div class=\"font-bold text-netflix-600 dark:text-rose-400 mb-1\">仓位定位：美股科技与消费互联网核心底仓</div>\n                <p class=\"text-slate-600 dark:text-slate-300 leading-relaxed\">\n                  凭借 30.1% ROIC 与近百亿美元年自由现金流，NFLX 已具备防御与进攻双重属性。在当前 ~18x 远期 P/E 区间，建议作为<strong>数字媒体与全球互联网消费赛道的超配核心持仓</strong>。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/70 border border-slate-200 dark:border-slate-700\">\n                <div class=\"font-bold text-teal-600 dark:text-teal-400 mb-1\">建仓与再平衡纪律</div>\n                <p class=\"text-slate-600 dark:text-slate-300 leading-relaxed\">\n                  建议在 16x-19x 远期 P/E 区间采取分批左侧布局策略；若后续广告增速超预期推动估值修复至 25x 以上，再结合季度营业利润率边际变化进行动态止盈平衡。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 可交互的季度基本面跟踪 KPI 核查清单 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">季度基本面跟踪 KPI 核查清单 (Checklist)</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400\">由于公司已停止披露季度用户数，机构需重点核查以下四大核心指标</p>\n              </div>\n              <span id=\"kpi-progress-badge\" class=\"px-2.5 py-1 rounded-full bg-netflix-500/10 text-netflix-600 dark:text-rose-400 text-xs font-bold\">已核查 2 / 4 项</span>\n            </div>\n\n            <div class=\"space-y-2.5 mt-4\" id=\"kpi-checklist\">\n              <label class=\"flex items-start space-x-3 p-3 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                <input type=\"checkbox\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded text-netflix-600 focus:ring-netflix-500\">\n                <div class=\"flex-1\">\n                  <div class=\"flex items-center justify-between\">\n                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">01. 恒定汇率下营收增速（FX-Neutral Revenue Growth）</span>\n                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold\">核心增长锚</span>\n                  </div>\n                  <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">剔除美元汇率扰动后，监测全公司营收是否稳健保持在 12%-15% 双位数增长通道。</p>\n                </div>\n              </label>\n\n              <label class=\"flex items-start space-x-3 p-3 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                <input type=\"checkbox\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded text-netflix-600 focus:ring-netflix-500\">\n                <div class=\"flex-1\">\n                  <div class=\"flex items-center justify-between\">\n                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">02. 营业利润率（Operating Margin）扩张斜率</span>\n                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">经营杠杆指标</span>\n                  </div>\n                  <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">跟踪全年营业利润率能否在 ~29%-30% 基础上每年稳步提升 150-200 个基点。</p>\n                </div>\n              </label>\n\n              <label class=\"flex items-start space-x-3 p-3 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                <input type=\"checkbox\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded text-netflix-600 focus:ring-netflix-500\">\n                <div class=\"flex-1\">\n                  <div class=\"flex items-center justify-between\">\n                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">03. 广告层级（Ad-Tier）变现进度与 $3B 目标兑现</span>\n                    <span class=\"text-[11px] font-mono text-rose-600 dark:text-rose-400 font-semibold\">第二曲线催化剂</span>\n                  </div>\n                  <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">监测自研广告技术栈在欧美及亚太主要市场的广告填充率、CPM 单价及广告收入翻倍进度。</p>\n                </div>\n              </label>\n\n              <label class=\"flex items-start space-x-3 p-3 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                <input type=\"checkbox\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded text-netflix-600 focus:ring-netflix-500\">\n                <div class=\"flex-1\">\n                  <div class=\"flex items-center justify-between\">\n                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">04. 年度自由现金流（FCF）转化与股票回购执行力度</span>\n                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">股东回报指标</span>\n                  </div>\n                  <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">核查内容现金支出纪律（~$17-18B）以及管理层在低估值区间加大股票回购注销的节奏。</p>\n                </div>\n              </label>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>Netflix (NASDAQ: NFLX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2025 财报及 2026 年 11 月市场一致预期</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公开公司财报、流媒体行业第三方收视监测数据及财务估值模型整理生成，旨在提供结构化的商业模式与投资逻辑参考。报告中涉及的 2026E 预测营收、广告收入目标及估值倍数均基于特定假设与市场一致预期，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与侧边导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-rose-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-rose-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-netflix-500', 'text-white', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border');\n        } else {\n          btn.classList.remove('bg-netflix-500', 'text-white', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. KPI 核查清单进度统计\n    // ==========================================\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const checkedCount = Array.from(checkboxes).filter(cb => cb.checked).length;\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${checkboxes.length} 项`;\n    }\n\n    // ==========================================\n    // 6. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let marginChartInstance = null;\n    let currentBizMode = 'region';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 模式 1：区域营收占比与月均 ARPU 对比（双轴混合图）\n      const regionConfig = {\n        type: 'bar',\n        data: {\n          labels: ['北美 (UCAN)', '欧洲中东非洲 (EMEA)', '拉丁美洲 (LATAM)', '亚太地区 (APAC)'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '营收贡献占比 (%)',\n              data: [44.2, 32.1, 11.9, 11.8],\n              backgroundColor: ['#E50914', '#3B82F6', '#06B6D4', '#6366F1'],\n              borderRadius: 6,\n              barThickness: 38,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '月均单用户收入 ARPU ($)',\n              data: [17.4, 11.3, 8.4, 7.6],\n              borderColor: '#10B981',\n              backgroundColor: '#10B981',\n              borderWidth: 2.5,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `营收占比: ${ctx.parsed.y}%`\n                  : `月均 ARPU: $${ctx.parsed.y}`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 55,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              max: 22,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#10B981', font: { size: 11 }, callback: v => '$' + v }\n            }\n          }\n        }\n      };\n\n      // 模式 2：2021 - 2026E 营收与自由现金流 (FCF) 增长趋势\n      const growthConfig = {\n        type: 'bar',\n        data: {\n          labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年总营收 ($B)',\n              data: [29.70, 31.62, 33.72, 39.00, 45.18, 51.20],\n              backgroundColor: 'rgba(59, 130, 246, 0.85)',\n              borderRadius: 5,\n              barThickness: 28,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '自由现金流 FCF ($B)',\n              data: [-0.16, 1.62, 6.93, 6.92, 9.46, 10.80],\n              borderColor: '#E50914',\n              backgroundColor: '#E50914',\n              borderWidth: 3,\n              pointRadius: 5,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 60,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: -2,\n              max: 14,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#E50914', font: { size: 11 }, callback: v => '$' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'region' ? regionConfig : growthConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnRegion = document.getElementById('btn-chart-region');\n      const btnGrowth = document.getElementById('btn-chart-growth');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'region') {\n        btnRegion.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-netflix-600 dark:text-white shadow-sm transition';\n        btnGrowth.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '全球四大区域营收结构与月均 ARPU 对比';\n        subEl.textContent = 'UCAN 贡献核心现金流，EMEA 与 APAC 驱动全球渗透率扩张';\n      } else {\n        btnGrowth.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-netflix-600 dark:text-white shadow-sm transition';\n        btnRegion.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '2021 - 2026E 营业收入与自由现金流 (FCF) 跃升趋势';\n        subEl.textContent = '2025 FCF 达 $9.46B 历史新高，2026E 营收迈向 $51.2B 大关';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '全球本地原创内容飞轮',\n            '提价权与低流失率',\n            '推荐算法与数据规模',\n            'ROIC 资本回报效率',\n            '广告与体育直播变现'\n          ],\n          datasets: [\n            {\n              label: 'Netflix (NFLX)',\n              data: [9.6, 9.5, 9.4, 9.7, 8.8],\n              borderColor: '#E50914',\n              backgroundColor: 'rgba(229, 9, 20, 0.20)',\n              pointBackgroundColor: '#E50914',\n              borderWidth: 2.5\n            },\n            {\n              label: '科技巨头生态 (YouTube/Prime)',\n              data: [6.8, 7.2, 9.0, 8.2, 9.3],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.14)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.8\n            },\n            {\n              label: '传统好莱坞流媒体 (Disney+/Max)',\n              data: [7.5, 6.2, 5.5, 4.2, 6.5],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initMarginChart() {\n      const ctx = document.getElementById('marginComparisonChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (marginChartInstance) marginChartInstance.destroy();\n      marginChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'Netflix (全球流媒体龙头)',\n            'Disney DTC (流媒体分部)',\n            'Warner Bros. Discovery (DTC)',\n            'Paramount+ / 二线传媒平均'\n          ],\n          datasets: [{\n            label: '流媒体业务营业利润率 (%)',\n            data: [29.2, 6.5, 3.8, -4.5],\n            backgroundColor: [\n              '#E50914',\n              '#3B82F6',\n              '#64748B',\n              '#94A3B8'\n            ],\n            borderRadius: 6,\n            barThickness: 24\n          }]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `估算营业利润率: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              min: -10,\n              max: 35,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initMarginChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      initBizChart();\n      initRadarChart();\n      initMarginChart();\n    });\n  </script>\n</body>\n</html>"};
